TLM.f("Sancti/10-04",{"officium":"S. Francisci Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","sections":{"Introitus":[{"k":"ref","la":"Gal 6:14"},{"k":"text","la":"Mihi autem absit gloriári, nisi in Cruce Dómini nostri Jesu Christi: per quem mihi mundus crucifíxus est, et ego mundo."},{"k":"ref","la":"Ps 141:2"},{"k":"text","la":"Voce mea ad Dóminum clamávi: voce mea ad Dóminum deprecátus sum."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem absit gloriári, nisi in Cruce Dómini nostri Jesu Christi: per quem mihi mundus crucifíxus est, et ego mundo."}],"Oratio":[{"k":"text","la":"Deus, qui Ecclésiam tuam, beáti Francisci méritis fœtu novæ prolis amplíficas: tríbue nobis; ex ejus imitatióne, terréna despícere et cœléstium donórum semper participatióne gaudére."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Gálatas"},{"k":"ref","la":"Gal 6:14-18"},{"k":"text","la":"Fratres: Mihi autem absit gloriári, nisi in Cruce Dómini nostri Jesu Christi: per quem mihi mundus crucifíxus est, et ego mundo. In Christo enim Jesu neque circumcísio áliquid valet neque præpútium, sed nova creatúra. Et quicúmque hanc régulam secúti fúerint, pax sin per illos et misericórdia, et super Israël Dei. De cetero nemo mihi moléstus sit: ego enim stígmata Dómini Jesu in córpore meo porto. Grátia Dómini nostri Jesu Christi cum spíritu vestro, fratres. Amen."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Francíscus pauper et húmilis cœlum dives ingréditur, hymnis cœléstibus honorátur. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Francíscus pauper et húmilis cœlum dives ingréditur, hymnis cœléstibus honorátur.","mark":"V"},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 11:25-30"},{"k":"text","la":"In illo témpore: Respóndens Jesus, dixit: Confíteor tibi, Pater, Dómine cœli et terræ, quia abscondísti hæc a sapiéntibus et prudéntibus, et revelásti ea párvulis. Ita, Pater: quóniam sic fuit plácitum ante te. Omnia mihi trádita sunt a Patre meo. Et nemo novit Fílium nisi Pater: neque Patrem quis novit nisi Fílius, et cui volúerit Fílius reveláre. Veníte ad me, omnes, qui laborátis et oneráti estis, et ego refíciam vos. Tóllite jugum meum super vos, et díscite a me, quia mitis sum et húmilis corde: et inveniétis réquiem animábus vestris. Jugum enim meum suave est et onus meum leve."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Múnera tibi, Dómine, dicata sanctífica: et, intercedénte beáto Francísco, ab omni nos culpárum labe purífica."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Ecclésiam tuam, quǽsumus, Dómine, grátia cœléstis amplíficet: quam beáti Francísci Confessóris tui illumináre voluísti gloriósis méritis et exémplis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"a42af1a51e1d8d91":{"t":"Gal 6, 14, Ps 141, 2\n(Gal 6, 14) Daleko od mene da bih se ičim drugim hvalio osim križem Gospodina našega Isusa Krista, po kojemu je meni svijet razapet, a ja svijetu. (Ps 141, 2) Glasom svojim Gospodinu vapijem, glasom svojim Gospodinu se molim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Gal 6, 14) Daleko od mene da bih se ičim drugim hvalio osim križem Gospodina našega Isusa Krista, po kojemu je meni svijet razapet, a ja svijetu."},"8b19de23b07214bd":{"t":"<i>Pomolimo se</i>.\nBože, koji Crkvu svoju zaslugama blaženoga Franje umnažaš novim potomstvom; udijeli nam da po njegovu primjeru zemaljsko preziremo i vazda se radujemo što smo dionici nebeskih darova.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"a6e5edb4c68d76a6":null,"5bdb7537c718fc7e":{"t":"Ps 36, 30-31\nPravednikova usta raspravljaju o mudrosti i njegov jezik govori o pravdi. Zakon mu je Božji u srcu, i noge mu neće posrnuti.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nFranjo siromah i ponizan ulazi bogat u nebo, nebeskim ga pjesmama slave. <i>Aleluja</i>."},"bb0bd8107f5e0717":{"t":"Mt 11, 25-30\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Zahvaljujem ti, Oče, Gospodaru neba i zemlje jer si ovo sakrio mudrima i razumnima, a objavio malenima. Da, Oče, jer ti se svidjelo tako! Moj je Otac predao meni sve, i nitko ne pozna Sina nego Otac, niti tko pozna Oca nego Sin i komu Sin hoće da objavi. Dođite k meni svi koji ste umorni i opterećeni i ja ću vas okrijepiti. Uzmite na sebe moj jaram i učite se od mene jer sam ja krotka i ponizna srca i naći ćete pokoj svojim dušama. Jer je moj jaram sladak i moje breme lako."},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć."},"479d04a4222edf78":{"t":"Posveti, Gospodine, darove tebi namijenjene i po zagovoru blaženoga Franje od svake nas ljage grijeha očisti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"43352d99b4b928c1":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada."},"20e4a8b6bc7847c6":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da nebeska milost raširi tvoju Crkvu, koju si se udostojao prosvijetliti slavnim zaslugama i primjerima blaženoga Franje, svojega priznavaoca.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
